// scripts/build-mcp-widgets.ts
// Builds apps/mcp-widgets as one self-contained HTML file and emits it as a TS module the
// mcp edge function serves as ui://mesaas/cards-v1.html (spec §6). Run: npm run build:mcp-widgets
// CI rebuilds and fails on any diff, so commit the regenerated file with the widget change.
// A widget change that alters tool shapes ships as cards-v2 (new URI), never over v1.
import { mkdir, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CONFIG = path.join(ROOT, 'apps/mcp-widgets/vite.config.ts');
const BUILT = path.join(ROOT, 'node_modules/.cache/mcp-widgets/index.html');
const OUT = path.join(ROOT, 'supabase/functions/mcp/ui/generated/cards-v1.ts');
const BUDGET_BYTES = 500 * 1024;

const HEADER = `// GENERATED by scripts/build-mcp-widgets.ts (npm run build:mcp-widgets). Do not edit.
// Source: apps/mcp-widgets/. Served by the mcp function as ui://mesaas/cards-v1.html.
// deno-fmt-ignore-file
// deno-lint-ignore-file
`;

async function main() {
  await build({ configFile: CONFIG, mode: 'production', logLevel: 'warn' });
  const html = await readFile(BUILT, 'utf8');
  if (/<script[^>]+\bsrc=|<link[^>]+\bhref=/i.test(html)) {
    throw new Error('mcp-widgets build is not single-file: found an external script or stylesheet');
  }
  const bytes = Buffer.byteLength(html, 'utf8');
  await mkdir(path.dirname(OUT), { recursive: true });
  await writeFile(OUT, `${HEADER}\nexport const CARDS_V1_HTML = ${JSON.stringify(html)};\n`);
  const kb = (bytes / 1024).toFixed(1);
  console.log(`cards-v1.html: ${bytes} bytes (${kb} KB raw), budget ${BUDGET_BYTES / 1024} KB`);
  console.log(`wrote ${path.relative(ROOT, OUT)}`);
  if (bytes > BUDGET_BYTES) {
    console.error(`cards-v1.html is over the ${BUDGET_BYTES / 1024} KB budget`);
    process.exit(1);
  }
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
